package com.oldschoolnetwork.store.lite;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import android.text.*;
import com.oldschoolnetwork.lite.*;
import org.json.*;
import java.util.*;

public final class MainActivity extends Activity {
 private final ArrayList<JSONObject> apps=new ArrayList<JSONObject>();private ListView list;private TextView status;private AutoCompleteTextView search;private BaseAdapter adapter;
 private String type="app",query="",sort="new",genre="",category="",view="catalog";private JSONArray genres=new JSONArray(),categories=new JSONArray();private int offset,serial;private boolean more;private final Handler ui=new Handler();
 public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.main);status=(TextView)findViewById(R.id.status);search=(AutoCompleteTextView)findViewById(R.id.search);list=(ListView)findViewById(R.id.apps);
  adapter=new BaseAdapter(){public int getCount(){return apps.size();}public Object getItem(int n){return apps.get(n);}public long getItemId(int n){return apps.get(n).optLong("id");}
   public View getView(int n,View row,android.view.ViewGroup parent){if(row==null)row=getLayoutInflater().inflate(R.layout.app_row,parent,false);JSONObject a=apps.get(n);((TextView)row.findViewById(R.id.name)).setText(a.optString("name"));((TextView)row.findViewById(R.id.developer)).setText("own".equals(a.optString("app_mode"))?a.optString("publisher_studio"):a.optString("original_dev"));((TextView)row.findViewById(R.id.rating)).setText(a.optString("rating_avg","—")+" · "+a.optInt("downloads")+" downloads");((TextView)row.findViewById(R.id.compatibility)).setText(Transfers.installed(MainActivity.this,a.optString("package_name"))>=0?"Installed":Transfers.newest(a)==null?"No compatible APK":"Free");Images.load(MainActivity.this,(ImageView)row.findViewById(R.id.icon),a.optString("icon_url"),96);return row;}};
  list.setAdapter(adapter);list.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> p,View v,int pos,long id){openApp((int)id);}});
  findViewById(R.id.tab_apps).setOnClickListener(new View.OnClickListener(){public void onClick(View v){type="app";view="catalog";category="";load(false);}});
  findViewById(R.id.tab_games).setOnClickListener(new View.OnClickListener(){public void onClick(View v){type="game";view="catalog";category="";load(false);}});
  findViewById(R.id.tab_profile).setOnClickListener(new View.OnClickListener(){public void onClick(View v){profile();}});
  findViewById(R.id.menu).setOnClickListener(new View.OnClickListener(){public void onClick(View v){menu();}});
  findViewById(R.id.filter).setOnClickListener(new View.OnClickListener(){public void onClick(View v){filter();}});
  findViewById(R.id.retry).setOnClickListener(new View.OnClickListener(){public void onClick(View v){load(false);}});
  findViewById(R.id.more).setOnClickListener(new View.OnClickListener(){public void onClick(View v){load(true);}});
  search.setOnEditorActionListener(new TextView.OnEditorActionListener(){public boolean onEditorAction(TextView v,int action,KeyEvent e){if(action==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH||(e!=null&&e.getKeyCode()==KeyEvent.KEYCODE_ENTER)){runSearch(search.getText().toString());return true;}return false;}});
  search.setThreshold(0);search.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> p,View v,int n,long id){runSearch(p.getItemAtPosition(n).toString());}});
  search.setOnFocusChangeListener(new View.OnFocusChangeListener(){public void onFocusChange(View v,boolean focus){if(focus&&search.length()==0)suggestions("");}});
  search.addTextChangedListener(new TextWatcher(){Runnable pending;public void beforeTextChanged(CharSequence s,int a,int c,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(pending!=null)ui.removeCallbacks(pending);final String text=s.toString();pending=new Runnable(){public void run(){suggestions(text);}};ui.postDelayed(pending,350);}public void afterTextChanged(Editable e){}});
  android.net.Uri uri=getIntent().getData();if(uri!=null&&uri.getQueryParameter("app_id")!=null){try{openApp(Integer.parseInt(uri.getQueryParameter("app_id")));}catch(Exception ignored){}}if(uri!=null&&uri.getQueryParameter("category")!=null)category=uri.getQueryParameter("category");
  if(getIntent().getIntExtra("download_app_id",0)>0)openApp(getIntent().getIntExtra("download_app_id",0));
  load(false);
 }
 private void openApp(int id){startActivity(new Intent(this,DetailsActivity.class).putExtra("app_id",id));}
 private void runSearch(String text){query=text.trim();view="catalog";type="";search.dismissDropDown();search.clearFocus();list.requestFocus();remember(query);JSONObject b=new JSONObject();try{b.put("query",query);}catch(Exception ignored){}Api.call(this,"store_record_search",b,false,new Api.Callback(){public void complete(JSONObject r,String e){}});load(false);}
 private void remember(String q){if(q.length()==0)return;ArrayList<String> values=new ArrayList<String>();values.add(q);for(String old:getSharedPreferences("search",0).getString("history","").split("\n"))if(old.length()>0&&!old.equals(q)&&values.size()<4)values.add(old);StringBuilder all=new StringBuilder();for(String v:values)all.append(v.replace('\n',' ')).append('\n');getSharedPreferences("search",0).edit().putString("history",all.toString()).commit();}
 private void suggestions(final String text){
  if(text.length()==0){String[] history=getSharedPreferences("search",0).getString("history","").trim().split("\n");if(history.length>0&&history[0].length()>0){search.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,history));if(search.hasFocus())search.showDropDown();}return;}
  JSONObject b=new JSONObject();try{b.put("query",text);}catch(Exception ignored){}Api.call(this,"store_search_suggestions",b,false,new Api.Callback(){public void complete(JSONObject r,String error){if(isFinishing()||!text.equals(search.getText().toString())||r==null)return;JSONArray list=r.optJSONArray("suggestions");ArrayList<String> names=new ArrayList<String>();if(list!=null)for(int i=0;i<list.length()&&i<3;i++)names.add(list.optJSONObject(i).optString("text"));search.setAdapter(new ArrayAdapter<String>(MainActivity.this,android.R.layout.simple_dropdown_item_1line,names));if(search.hasFocus())search.showDropDown();}});
 }
 private void load(final boolean append){
  final int request=++serial;if(!append)offset=0;final boolean account=!"catalog".equals(view);if(account&&Api.account(this)==null){status.setText("Sign in with ON Core Lite to open your "+view+".");apps.clear();adapter.notifyDataSetChanged();return;}
  JSONObject b=new JSONObject();try{b.put("offset",offset).put("sdk",Build.VERSION.SDK_INT).put("type",type).put("query",query).put("sort",sort).put("genre",genre).put("category",category).put("compatible",true);}catch(Exception ignored){}
  status.setText("Loading…");findViewById(R.id.retry).setVisibility(View.GONE);
  Api.call(this,account?("library".equals(view)?"store_library":"store_favorites"):"store_catalog_lite",b,account,new Api.Callback(){public void complete(JSONObject r,String error){if(isFinishing()||request!=serial)return;if(error!=null){status.setText("Could not refresh. "+error);findViewById(R.id.retry).setVisibility(View.VISIBLE);if(!account&&!append&&query.length()==0&&category.length()==0)cached(request);return;}
   JSONArray rows=r.optJSONArray("apps");if(!append)apps.clear();if(rows!=null)for(int i=0;i<rows.length();i++)if(rows.optJSONObject(i)!=null)apps.add(rows.optJSONObject(i));genres=r.optJSONArray("genres")==null?genres:r.optJSONArray("genres");categories=r.optJSONArray("categories")==null?categories:r.optJSONArray("categories");offset=r.optInt("next_offset",apps.size());more=r.optBoolean("has_more");findViewById(R.id.more).setVisibility(more?View.VISIBLE:View.GONE);status.setText(apps.isEmpty()?"No applications match these filters.":view.equals("catalog")?(type.equals("game")?"Games":"Applications"):view.equals("library")?"Your acquired applications":"Favorites");adapter.notifyDataSetChanged();if(!account&&!append&&query.length()==0&&category.length()==0)saveCache(r);
  }});
 }
 private void saveCache(JSONObject result){final String data=result.toString(),name="catalog-"+(type.equals("game")?"game":"app")+".json";Api.WORK.execute(new Runnable(){public void run(){try{java.io.OutputStream out=openFileOutput(name,0);try{out.write(data.getBytes("UTF-8"));}finally{out.close();}}catch(Exception ignored){}}});}
 private void cached(final int request){final String name="catalog-"+(type.equals("game")?"game":"app")+".json";Api.WORK.execute(new Runnable(){public void run(){try{java.io.InputStream in=openFileInput(name);java.io.ByteArrayOutputStream data=new java.io.ByteArrayOutputStream();try{byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){data.write(b,0,n);if(data.size()>2*1024*1024)return;}}finally{in.close();}final JSONObject saved=new JSONObject(new String(data.toByteArray(),"UTF-8"));ui.post(new Runnable(){public void run(){if(isFinishing()||request!=serial||!view.equals("catalog"))return;apps.clear();JSONArray rows=saved.optJSONArray("apps");if(rows!=null)for(int i=0;i<rows.length();i++)apps.add(rows.optJSONObject(i));genres=saved.optJSONArray("genres")==null?new JSONArray():saved.optJSONArray("genres");categories=saved.optJSONArray("categories")==null?new JSONArray():saved.optJSONArray("categories");status.setText("Catalogue could not refresh. Showing the last saved data.");findViewById(R.id.more).setVisibility(View.GONE);adapter.notifyDataSetChanged();}});}catch(Exception ignored){}}});}
 protected void onResume(){super.onResume();if(!view.equals("catalog")&&Api.account(this)==null){serial++;apps.clear();adapter.notifyDataSetChanged();status.setText("Sign in with ON Core Lite to open your "+view+".");}}
 private void profile(){JSONObject account=Api.account(this);if(account==null){new AlertDialog.Builder(this).setTitle("ON Account").setMessage("ON Core Lite is required to sign in and use your library, favorites and reviews.").setPositiveButton("Sign in",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){Api.signIn(MainActivity.this);}}).setNegativeButton("Close",null).show();return;}
  new AlertDialog.Builder(this).setTitle("@"+account.optString("username")).setItems(new String[]{"Library","Favorites","ON Account","Refresh"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){if(n<2){view=n==0?"library":"favorites";load(false);}else if(n==2)Api.signIn(MainActivity.this);else load(false);}}).show();
 }
 private void menu(){String[] labels=new String[categories.length()+3];labels[0]="Top charts";labels[1]="Refresh";labels[2]="Settings";for(int i=0;i<categories.length();i++)labels[i+3]=categories.optJSONObject(i).optString("name");new AlertDialog.Builder(this).setTitle("ON Store Lite").setItems(labels,new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){if(n==0){sort="downloads";view="catalog";load(false);}else if(n==1)load(false);else if(n==2)settings();else{category=categories.optJSONObject(n-3).optString("slug");view="catalog";load(false);}}}).show();}
 private void settings(){new AlertDialog.Builder(this).setTitle("Lite settings").setMessage("Catalogues load in pages of 12. Images are sampled and cached within a fixed memory budget. Downloads require verified HTTPS and APK checksums. Lite releases are updated only when published separately.").setPositiveButton("Close",null).show();}
 private void filter(){View form=getLayoutInflater().inflate(R.layout.filter,null);final Spinner sorts=(Spinner)form.findViewById(R.id.sort),g=(Spinner)form.findViewById(R.id.genre);sorts.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Newest","Name","Downloads","Rating"}));final String[] ids={"new","name","downloads","rating"};for(int i=0;i<ids.length;i++)if(ids[i].equals(sort))sorts.setSelection(i);ArrayList<String> options=new ArrayList<String>();options.add("All genres");for(int i=0;i<genres.length();i++)options.add(genres.optString(i));g.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,options));if(options.contains(genre))g.setSelection(options.indexOf(genre));new AlertDialog.Builder(this).setTitle("Filter").setView(form).setPositiveButton("Apply",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){sort=ids[sorts.getSelectedItemPosition()];genre=g.getSelectedItemPosition()==0?"":g.getSelectedItem().toString();load(false);}}).setNegativeButton("Cancel",null).show();}
}
